  public static String getDisabledUsersDN (String userDN) throws GeneralException {

    if (logger.isTraceEnabled()) {
      logger.trace("Alpha-Rule-Termination-RuleLibrary -> Entered to getDisabledUsersDN Method!!!");
    }
    String disabledUsersDN = null;
    try {
      logger.debug("Alpha-Rule-Termination-RuleLibrary - getDisabledUsersDN -> User Distinguished Name : "+userDN);
      String cnValueOfUserDN = null;
      if (Util.isNotNullOrEmpty(userDN)) {
        LdapName ldapName = new LdapName(userDN);
        if (ldapName != null) {
          List<Rdn> rdnList = ldapName.getRdns();
          for (Rdn rdn : rdnList) {
            logger.debug("Alpha-Rule-Termination-RuleLibrary - getDisabledUsersDN -> RDN Type : "+rdn.getType());
            if (rdn.getType().equalsIgnoreCase("cn")) {
              cnValueOfUserDN = rdn.getValue();
            }
          }
        }
        logger.debug("Alpha-Rule-Termination-RuleLibrary - getDisabledUsersDN -> User CommonName from DN : "+cnValueOfUserDN);

        String adDomain = getValueFromCustomObject (CUSTOM_OBJECT_NAME_FOR_TERMINATION, "AD_Domain");
        String adBaseOU = getValueFromCustomObject (CUSTOM_OBJECT_NAME_FOR_TERMINATION, "AD_BaseOU");
        String adDisabledOU = getValueFromCustomObject (CUSTOM_OBJECT_NAME_FOR_TERMINATION, "AD_DisabledOU");
        if (Util.isNotNullOrEmpty(adDomain) && Util.isNotNullOrEmpty(adBaseOU) && Util.isNotNullOrEmpty(adDisabledOU) && Util.isNotNullOrEmpty(cnValueOfUserDN)) {
          disabledUsersDN = "CN=" +cnValueOfUserDN+ "," +adDisabledOU+ "," +adBaseOU+ "," +adDomain;
        }
        logger.debug("Alpha-Rule-Termination-RuleLibrary - getDisabledUsersDN -> Modified (Disabled) User DN : "+disabledUsersDN);
      }
    }
    catch (GeneralException exp) {
      logger.error("Alpha-Rule-Termination-RuleLibrary - getDisabledUsersDN -> Caught GeneralException : "+exp.getMessage());
    }
    catch (Exception exp) {
      logger.error("Alpha-Rule-Termination-RuleLibrary - getDisabledUsersDN -> Caught JAVA Exception : "+exp.getMessage());
    }
    if (logger.isTraceEnabled()) {
      logger.trace("Alpha-Rule-Termination-RuleLibrary -> getDisabledUsersDN method Ended!!!");
    }
    return disabledUsersDN;
  }*/

  public static String generateADPassword (String pwdPolicyName) throws GeneralException {

    if (logger.isTraceEnabled()) {
      logger.trace("Alpha-Rule-Termination-RuleLibrary -> Entered to generateADPassword Method!!!");
    }
    String password = null;
    if (Util.isNotNullOrEmpty(pwdPolicyName)) {
      PasswordPolicy policy = context.getObjectByName(PasswordPolicy.class, pwdPolicyName);
      password = new PasswordGenerator(context).generatePassword(policy);
    }
    if (logger.isTraceEnabled()) {
      logger.trace("Alpha-Rule-Termination-RuleLibrary -> generateADPassword method Ended!!!");
    }
    return password;
  }
